 * Display-column width calculations per code point.
 */

const SOFT_HYPHEN = 0x00ad

function inRange(cp, lo, hi) {
  return cp >= lo && cp <= hi
}

function isCombining(cp) {
  return (
    inRange(cp, 0x0300, 0x036f) ||
    inRange(cp, 0x1ab0, 0x1aff) ||
    inRange(cp, 0x20d0, 0x20f0) ||
    inRange(cp, 0xfe20, 0xfe2f)
  )
}

function isWide(cp) {
  return (
    inRange(cp, 0x1100, 0x115f) ||
    inRange(cp, 0x2e80, 0xa4cf) ||
    inRange(cp, 0xac00, 0xd7a3) ||
    inRange(cp, 0xf900, 0xfaff) ||
    inRange(cp, 0xfe30, 0xfe4f) ||
    inRange(cp, 0xff00, 0xff60) ||
    inRange(cp, 0xffe0, 0xffe6)
  )
}

/** Width in display columns of a single code point (number). */
export function codePointWidth(cp) {
  if (cp === SOFT_HYPHEN) return 0
  if (isCombining(cp)) return 0
  if (isWide(cp)) return 2
  return 1
}

/** Split a string into an array of code point strings. */
export function toCodePoints(str) {
  return Array.from(str)
}

/** Width in display columns of a string, per code point. */
export function stringWidth(str) {
  let w = 0
  for (const ch of str) {
    w += codePointWidth(ch.codePointAt(0))
  }
  return w
}
