 * Split raw input text into paragraphs of words.
 */

const BLANK_LINE = /^[ \t]*$/

/**
 * @param {string} input raw stdin text
 * @returns {string[][]} array of paragraphs, each an array of words
 */
export function parseParagraphs(input) {
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines = lines.slice(0, -1)
  }

  const paragraphs = []
  let current = []
  let inParagraph = false

  for (const line of lines) {
    if (BLANK_LINE.test(line)) {
      if (inParagraph) {
        paragraphs.push(current)
        current = []
        inParagraph = false
      }
      continue
    }
    const words = line.split(/[ \t]+/).filter((w) => w.length > 0)
    current.push(...words)
    inParagraph = true
  }

  if (inParagraph) {
    paragraphs.push(current)
  }

  return paragraphs
}
"}

